import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || !validateSession(sessionToken)) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        String assetType = req.getParameter("type");
        String owner = req.getParameter("owner");
        String status = req.getParameter("status");

        // Build dynamic query based on filters
        StringBuilder query = new StringBuilder("SELECT asset_id, name, owner, status, value FROM assets WHERE 1=1");
        if (assetType != null && !assetType.isEmpty()) {
            query.append(" AND asset_type = '").append(sanitizeType(assetType)).append("'");
        }
        if (owner != null && !owner.isEmpty()) {
            query.append(" AND owner = '").append(owner).append("'");
        }
        if (status != null && !status.isEmpty()) {
            query.append(" AND status = '").append(status).append("'");
        }

        log.info("Executing asset search for session: " + sessionToken.substring(0, 8) + "...");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"id\": \"%s\", \"name\": \"%s\", \"owner\": \"%s\", \"status\": \"%s\", \"value\": %.2f}",
                    rs.getString("asset_id"),
                    rs.getString("name"),
                    rs.getString("owner"),
                    rs.getString("status"),
                    rs.getDouble("value"));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String sanitizeType(String input) {
        // Only allow known asset types
        String[] allowed = {"hardware", "software", "license", "infrastructure", "data"};
        for (String a : allowed) {
            if (a.equalsIgnoreCase(input)) return a;
        }
        return "unknown";
    }

    private boolean validateSession(String token) {
        // Validates against session store
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT 1 FROM sessions WHERE token = ? AND expires_at > NOW()")) {
            ps.setString(1, token);
            return ps.executeQuery().next();
        } catch (SQLException e) {
            return false;
        }
    }
}
